import type { Soru } from "../sorular";

export const P07: Soru[] = [
  { id: "p07-001", k: "Doğa", s: "Bitki hücresinde fotosentez hangi organelde gerçekleşir?", d: "Kloroplast", y: ["Mitokondri", "Ribozom"], a: "Fotosentez, içinde klorofil bulunan kloroplastlarda gerçekleşir. Mitokondri ise hücresel solunumun yapıldığı organeldir." },
  { id: "p07-002", k: "Doğa", s: "Bitkiler fotosentez için havadan hangi gazı alır?", d: "Karbondioksit", y: ["Oksijen", "Azot"], a: "Bitkiler karbondioksidi yapraklarındaki gözeneklerden alır ve suyla birlikte şeker üretmek için kullanır." },
  { id: "p07-003", k: "Doğa", s: "Fotosentez sonucunda havaya hangi gaz verilir?", d: "Oksijen", y: ["Karbondioksit", "Metan"], a: "Fotosentezin yan ürünü oksijendir. Soluduğumuz oksijenin büyük kısmı bitkilerin, alglerin ve siyanobakterilerin fotosentezinden gelir." },
  { id: "p07-004", k: "Doğa", s: "Fotosentezde açığa çıkan oksijen hangi molekülün parçalanmasından gelir?", d: "Su", y: ["Karbondioksit", "Glikoz"], a: "Işığa bağlı tepkimelerde su molekülleri parçalanır ve oksijen açığa çıkar. Bu, izotoplarla yapılan deneylerle gösterilmiştir." },
  { id: "p07-005", k: "Doğa", s: "Yapraklara yeşil rengini veren pigment hangisidir?", d: "Klorofil", y: ["Karoten", "Antosiyanin"], a: "Klorofil ışık enerjisini yakalayan ana pigmenttir. Karoten turuncu-sarı, antosiyanin ise kırmızı-mor renk verir." },
  { id: "p07-006", k: "Doğa", s: "Klorofil ışığın hangi rengini en çok yansıtır?", d: "Yeşil", y: ["Kırmızı", "Mavi"], a: "Klorofil kırmızı ve mavi ışığı güçlü biçimde soğurur, yeşil ışığın çoğunu yansıtır. Bu yüzden yapraklar yeşil görünür." },
  { id: "p07-007", k: "Doğa", s: "Fotosentezin ışığa bağlı tepkimeleri kloroplastın hangi kısmında olur?", d: "Tilakoit zarlarında", y: ["Stromada", "Dış zarda"], a: "Klorofil, kloroplastın içindeki yassı keseciklerin, yani tilakoitlerin zarlarında bulunur. Işığa bağlı tepkimeler burada gerçekleşir." },
  { id: "p07-008", k: "Doğa", s: "Karbondioksidin şekere dönüştürüldüğü Calvin döngüsü kloroplastın neresinde işler?", d: "Stromada", y: ["Tilakoit zarında", "Hücre zarında"], a: "Calvin döngüsü kloroplastın sıvı kısmı olan stromada gerçekleşir. Işık tepkimelerinin ürettiği ATP ve NADPH burada kullanılır." },
  { id: "p07-009", k: "Doğa", s: "Calvin döngüsünde karbondioksidi bağlayan enzim hangisidir?", d: "Rubisco", y: ["Amilaz", "Katalaz"], a: "Rubisco, karbondioksidi organik moleküle bağlayan enzimdir. Dünyada en bol bulunan protein olduğu kabul edilir." },
  { id: "p07-010", k: "Doğa", s: "Fotosentezin genel denkleminde ürün olarak yazılan şeker hangisidir?", d: "Glikoz", y: ["Laktoz", "Maltoz"], a: "Ders kitaplarındaki denklem 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ şeklindedir. Burada C₆H₁₂O₆ glikozu gösterir." },
  { id: "p07-011", k: "Doğa", s: "Bitkiler fazla şekeri depolamak için çoğunlukla hangi maddeye dönüştürür?", d: "Nişasta", y: ["Glikojen", "Kitin"], a: "Bitkiler glikozu nişasta olarak depolar. Glikojen hayvanların ve mantarların depo şekeridir, kitin ise yapı maddesidir." },
  { id: "p07-012", k: "Doğa", s: "Yapraklarda gaz alışverişini sağlayan küçük açıklıklara ne denir?", d: "Stoma", y: ["Kütikula", "Floem"], a: "Stomalar (gözenekler) çoğunlukla yaprağın alt yüzünde bulunur. Karbondioksit girişi, oksijen ve su buharı çıkışı buradan olur." },
  { id: "p07-013", k: "Doğa", s: "Stomaların açılıp kapanmasını sağlayan hücrelere ne ad verilir?", d: "Bekçi hücreleri", y: ["Palizat hücreleri", "Kök tüyü hücreleri"], a: "Her stomanın iki yanında fasulye biçimli bekçi hücreleri vardır. Su alıp şiştiklerinde stoma açılır, su kaybettiklerinde kapanır." },
  { id: "p07-014", k: "Doğa", s: "Bitkilerin yapraklardan su buharı kaybetmesine ne denir?", d: "Terleme", y: ["Fotoliz", "Çimlenme"], a: "Terleme (transpirasyon), suyun çoğunlukla stomalardan buhar olarak çıkmasıdır. Kökten aldığı suyun büyük kısmını bitki bu yolla kaybeder." },
  { id: "p07-015", k: "Doğa", s: "Suyu ve mineralleri kökten yapraklara taşıyan iletim dokusu hangisidir?", d: "Ksilem", y: ["Floem", "Epidermis"], a: "Ksilem (odun borusu) suyu ve mineralleri kökten yukarı taşır. Floem ise yaprakta üretilen şekerleri bitkinin her yerine dağıtır." },
  { id: "p07-016", k: "Doğa", s: "Yapraklarda üretilen şekeri bitkinin diğer kısımlarına taşıyan doku hangisidir?", d: "Floem", y: ["Ksilem", "Kambiyum"], a: "Floem (soymuk borusu), fotosentezle üretilen şekerleri yapraklardan kök, meyve ve büyüyen uçlara taşır." },
  { id: "p07-017", k: "Doğa", s: "Ağaç gövdesinin enine kalınlaşmasını sağlayan büyüme dokusu hangisidir?", d: "Kambiyum", y: ["Epidermis", "Kütikula"], a: "Kambiyum, ksilem ile floem arasında bulunan bölünür hücre tabakasıdır. Her yıl yeni iletim dokusu üreterek gövdeyi kalınlaştırır." },
  { id: "p07-018", k: "Doğa", s: "Kök ve gövdenin ucunda boyca uzamayı sağlayan dokuya ne denir?", d: "Uç meristem", y: ["Kambiyum", "Kütikula"], a: "Uç meristemler sürekli bölünen hücrelerden oluşur ve bitkinin boyca uzamasını sağlar. Kambiyum ise enine büyümeden sorumludur." },
  { id: "p07-019", k: "Doğa", s: "Kökte su ve mineral emilen yüzeyi büyük ölçüde artıran yapılar hangileridir?", d: "Kök tüyleri", y: ["Stomalar", "Kök şapkası"], a: "Kök tüyleri, kök yüzeyindeki hücrelerin ince uzantılarıdır. Emme yüzeyini çok artırarak su ve mineral alımını kolaylaştırır." },
  { id: "p07-020", k: "Doğa", s: "Kökün ucunu toprakta ilerlerken korumaya yarayan yapı hangisidir?", d: "Kök şapkası", y: ["Kök tüyü", "Koltuk tomurcuğu"], a: "Kök şapkası, kök ucundaki bölünen hücreleri bir başlık gibi örter. Toprakta ilerlerken aşınan hücreleri sürekli yenilenir." },
  { id: "p07-021", k: "Doğa", s: "Havucun yediğimiz turuncu kısmı bitkinin hangi organıdır?", d: "Kök", y: ["Gövde", "Meyve"], a: "Havucun yenen kısmı besin depolayan kalın bir kazık köktür. Yeşil yaprakları ise toprağın üstünde kalır." },
  { id: "p07-022", k: "Doğa", s: "Patates yumrusu botanik olarak bitkinin hangi organıdır?", d: "Toprak altı gövde", y: ["Kök", "Meyve"], a: "Patates yumrusu nişasta depolayan bir gövdedir. Üzerindeki \"gözler\" aslında tomurcuktur ve filizlenip yeni bitki verebilir." },
  { id: "p07-023", k: "Doğa", s: "Soğanın üst üste dizili etli katmanları hangi organın değişmiş hâlidir?", d: "Yaprak", y: ["Kök", "Meyve"], a: "Soğan, kısa bir gövde etrafında dizilmiş etli yapraklardan oluşur. Bu yapraklar bitkinin besin deposu işlevini görür." },
  { id: "p07-024", k: "Doğa", s: "Kaktüslerin dikenleri hangi organın değişmiş hâlidir?", d: "Yaprak", y: ["Gövde", "Kök"], a: "Kaktüs dikenleri değişmiş yapraklardır. Su kaybını azaltır ve bitkiyi korur; fotosentezi ise yeşil, etli gövde yapar." },
  { id: "p07-025", k: "Doğa", s: "Bezelyenin bir yere tutunmasını sağlayan ince sülükler hangi organın değişmiş hâlidir?", d: "Yaprak", y: ["Kök", "Çiçek"], a: "Bezelyede sülükler, bileşik yaprağın uçtaki yaprakçıklarının değişmesiyle oluşur. Dokundukları desteğe sarılarak bitkiyi yukarı taşır." },
  { id: "p07-026", k: "Doğa", s: "Kerevizin yenen uzun sapları bitkinin hangi kısmıdır?", d: "Yaprak sapı", y: ["Toprak altı gövde", "Kök"], a: "Sap kerevizinin yenen kalın sapları yaprak saplarıdır. Ucunda yaprak ayası bulunur." },
  { id: "p07-027", k: "Doğa", s: "Brokolinin yediğimiz kısmı ağırlıklı olarak nedir?", d: "Çiçek tomurcukları", y: ["Yapraklar", "Kökler"], a: "Brokoli, henüz açmamış çiçek tomurcuklarından oluşan bir çiçek durumudur. Hasat edilmezse tomurcuklar sarı çiçeklere dönüşür." },
  { id: "p07-028", k: "Doğa", s: "Tarçın baharatı bitkinin hangi kısmından elde edilir?", d: "Ağaç kabuğu", y: ["Tohum", "Kök"], a: "Tarçın, Cinnamomum cinsi ağaçların iç kabuğu soyulup kurutularak elde edilir. Kuruyan kabuk kendiliğinden rulo şeklini alır." },
  { id: "p07-029", k: "Doğa", s: "Zencefilin mutfakta kullanılan kısmı botanik olarak nedir?", d: "Rizom", y: ["Kök", "Meyve"], a: "Zencefil, toprak altında yatay büyüyen bir gövde olan rizomdur. Kök gibi görünse de boğumları ve tomurcukları vardır." },
  { id: "p07-030", k: "Doğa", s: "Karanfil baharatı bitkinin hangi kısmıdır?", d: "Kurutulmuş çiçek tomurcuğu", y: ["Tohum", "Ağaç kabuğu"], a: "Karanfil baharatı, karanfil ağacının (Syzygium aromaticum) açmamış çiçek tomurcuklarının kurutulmasıyla elde edilir." },
  { id: "p07-031", k: "Doğa", s: "Safran, safran bitkisinin hangi kısmından elde edilir?", d: "Dişicik tepeciklerinden", y: ["Taç yapraklarından", "Soğanından"], a: "Safran, Crocus sativus çiçeğinin kırmızı dişicik tepeciklerinin elle toplanıp kurutulmasıyla elde edilir. Bu yüzden çok pahalıdır." },
  { id: "p07-032", k: "Doğa", s: "Karabiber tanesi botanik olarak nedir?", d: "Kurutulmuş meyve", y: ["Çiçek tomurcuğu", "Kök parçası"], a: "Karabiber, Piper nigrum sarmaşığının olgunlaşmamış meyvelerinin kurutulmasıyla elde edilir." },
  { id: "p07-033", k: "Doğa", s: "Vanilya, hangi bitki ailesinin üyesidir?", d: "Orkideler", y: ["Baklagiller", "Gülgiller"], a: "Vanilya bir orkide türüdür. Baharat, bu orkidenin uzun kapsül meyvelerinin işlenmesiyle elde edilir." },
  { id: "p07-034", k: "Doğa", s: "Çiçekte polen üreten erkek organa ne ad verilir?", d: "Ercik", y: ["Dişicik", "Çanak yaprak"], a: "Ercik, sapçık ve onun ucundaki başçıktan oluşur. Polenler başçıkta üretilir." },
  { id: "p07-035", k: "Doğa", s: "Erciğin polenlerin üretildiği uç kısmına ne denir?", d: "Başçık", y: ["Yumurtalık", "Tepecik"], a: "Başçık (anter), erciğin ucundaki keseciklerdir. Olgunlaşınca açılır ve polenleri serbest bırakır." },
  { id: "p07-036", k: "Doğa", s: "Dişiciğin polenleri yakalayan yapışkan uç kısmına ne denir?", d: "Tepecik", y: ["Başçık", "Sapçık"], a: "Tepecik genellikle yapışkan ya da tüylüdür ve gelen polenleri tutar. Polen buradan yumurtalığa doğru bir tüp uzatır." },
  { id: "p07-037", k: "Doğa", s: "Bitkilerde tozlaşma ne demektir?", d: "Polenin tepeciğe taşınması", y: ["Tohumun çimlenmesi", "Meyvenin olgunlaşması"], a: "Tozlaşma, polenin başçıktan dişiciğin tepeciğine ulaşmasıdır. Rüzgâr, su ya da hayvanlar bu taşımayı yapabilir." },
  { id: "p07-038", k: "Doğa", s: "Döllenmeden sonra çiçeğin yumurtalığı neye dönüşür?", d: "Meyveye", y: ["Tohuma", "Yaprağa"], a: "Döllenmeden sonra yumurtalık gelişip meyveyi, içindeki tohum taslakları da tohumları oluşturur." },
  { id: "p07-039", k: "Doğa", s: "Yumurtalığın içindeki tohum taslağı döllenince neye dönüşür?", d: "Tohuma", y: ["Meyve kabuğuna", "Çanak yaprağa"], a: "Tohum taslağı döllenince embriyo, besin dokusu ve tohum kabuğu gelişir; böylece tohum oluşur." },
  { id: "p07-040", k: "Doğa", s: "Çiçekli bitkilerin çift döllenmesinde ikinci sperm hangi dokuyu oluşturur?", d: "Endosperm", y: ["Tohum kabuğu", "Meyve eti"], a: "Bir sperm yumurtayı döllerken diğeri iki kutup çekirdeğiyle birleşir ve embriyoyu besleyen endospermi oluşturur." },
  { id: "p07-041", k: "Doğa", s: "Aşağıdaki bitkilerden hangisi rüzgârla tozlaşır?", d: "Mısır", y: ["Orkide", "Ayçiçeği"], a: "Mısır, buğday gibi çimengiller rüzgârla tozlaşır. Erkek çiçeklerinden (püskül) saçılan bol polen rüzgârla dişi çiçeklere ulaşır." },
  { id: "p07-042", k: "Doğa", s: "Rüzgârla tozlaşan çiçeklerin tipik özelliği hangisidir?", d: "Bol ve hafif polen", y: ["Parlak renkli taç yaprak", "Bol nektar"], a: "Rüzgârla tozlaşan bitkiler hayvan çekmek zorunda olmadığından gösterişsiz çiçekler açar ama çok miktarda hafif polen üretir." },
  { id: "p07-043", k: "Doğa", s: "Arılar, birçok çiçekte insanların göremediği desenleri hangi ışık sayesinde görür?", d: "Morötesi ışık", y: ["Kızılötesi ışık", "Mikrodalga"], a: "Arılar morötesi ışığı görebilir. Birçok çiçekte yalnızca morötesinde görünen desenler, arıları nektara yönlendirir." },
  { id: "p07-044", k: "Doğa", s: "Bir çiçeğin aynı türden başka bir bireyin poleniyle tozlaşmasına ne denir?", d: "Çapraz tozlaşma", y: ["Kendi kendine tozlaşma", "Vejetatif üreme"], a: "Çapraz tozlaşma genetik çeşitliliği artırır. Birçok bitki kendi poleniyle döllenmeyi engelleyen düzenlere sahiptir." },
  { id: "p07-045", k: "Doğa", s: "Gece açan, beyaz ve güçlü kokulu çiçekleri çoğunlukla hangi hayvanlar tozlaştırır?", d: "Güveler", y: ["Sinek kuşları", "Bal arıları"], a: "Karanlıkta renk değil koku ve açık renk işe yarar. Gece açan beyaz, kokulu çiçekler çoğunlukla güveler, bazı bölgelerde yarasalar tarafından tozlaştırılır." },
  { id: "p07-046", k: "Doğa", s: "Dünyanın en büyük tek çiçeğini açan, leş kokulu bitki hangisidir?", d: "Rafflesia arnoldii", y: ["Lotus", "Manolya"], a: "Güneydoğu Asya'da yetişen Rafflesia'nın çiçeği yaklaşık 1 metre çapa ulaşabilir. Leş kokusuyla tozlaştırıcı sinekleri çeker." },
  { id: "p07-047", k: "Doğa", s: "Ayçiçeğinin tek bir büyük çiçek gibi görünen başı aslında nedir?", d: "Çok sayıda küçük çiçek", y: ["Tek bir dev çiçek", "Yaprak kümesi"], a: "Ayçiçeği başı yüzlerce küçük çiçekten oluşan bir çiçek durumudur. Ortadaki her küçük çiçek bir çekirdek (meyve) verebilir." },
  { id: "p07-048", k: "Doğa", s: "Çiçeği dıştan saran, çoğunlukla yeşil koruyucu yapraklara ne denir?", d: "Çanak yaprak", y: ["Taç yaprak", "Tepecik"], a: "Çanak yapraklar tomurcuk hâlindeki çiçeği korur. Renkli taç yapraklar ise genellikle tozlaştırıcıları çekmeye yarar." },
  { id: "p07-049", k: "Doğa", s: "Çiçeklerin salgıladığı nektar temelde nedir?", d: "Şekerli bir sıvı", y: ["Polen tozu", "Reçine"], a: "Nektar şekerce zengin bir sıvıdır. Tozlaştırıcı hayvanlar için bir ödüldür; arılar bal yapmak için nektar toplar." },
  { id: "p07-050", k: "Doğa", s: "Toz gibi küçük orkide tohumları doğada çimlenmek için çoğunlukla neye ihtiyaç duyar?", d: "Bir mantar ortağına", y: ["Orman yangınına", "Kuş sindirimine"], a: "Orkide tohumlarında besin deposu çok azdır. Çimlenip gelişebilmek için genellikle onlara besin sağlayan mikorizal mantarlarla ortaklık kurarlar." },
  { id: "p07-051", k: "Doğa", s: "Tohumları meyve içinde değil, kozalak pullarında açıkta gelişen bitki grubu hangisidir?", d: "Açık tohumlular", y: ["Kapalı tohumlular", "Eğrelti otları"], a: "Çam, ladin ve köknar gibi açık tohumlularda tohum bir meyve tarafından sarılmaz. Kapalı tohumlularda ise tohum meyvenin içindedir." },
  { id: "p07-052", k: "Doğa", s: "Eğrelti otları neyle çoğalır?", d: "Sporlarla", y: ["Tohumlarla", "Meyvelerle"], a: "Eğrelti otları tohum üretmez; sporlarla çoğalır. Sporlar genellikle yaprakların alt yüzündeki kahverengi keseciklerde oluşur." },
  { id: "p07-053", k: "Doğa", s: "Ksilem ve floem gibi iletim dokuları bulunmayan kara bitkisi grubu hangisidir?", d: "Karayosunları", y: ["Eğrelti otları", "Çamlar"], a: "Karayosunlarında gerçek iletim dokusu yoktur. Bu yüzden genellikle küçük kalır ve nemli yerlerde yaşarlar." },
  { id: "p07-054", k: "Doğa", s: "Buğday ve mısır gibi tek çenekli bitkilerde yaprak damarları genellikle nasıl dizilir?", d: "Paralel", y: ["Ağ şeklinde", "Işınsal"], a: "Tek çeneklilerde damarlar yaprak boyunca paralel uzanır. Çift çeneklilerde ise genellikle ağ şeklinde dallanır." },
  { id: "p07-055", k: "Doğa", s: "Hangi bitkinin tohumunda iki çenek yaprağı bulunur?", d: "Fasulye", y: ["Mısır", "Buğday"], a: "Fasulye çift çenekli bir bitkidir; tohumu kolayca iki yarıya ayrılır. Mısır ve buğday ise tek çeneklidir." },
  { id: "p07-056", k: "Doğa", s: "Bitkilerin ışık kaynağına doğru yönelerek büyümesine ne denir?", d: "Fototropizma", y: ["Gravitropizma", "Tigmotropizma"], a: "Fototropizmada gövde ışığa doğru eğilir. Bunun nedeni gölgede kalan taraftaki hücrelerin daha fazla uzamasıdır." },
  { id: "p07-057", k: "Doğa", s: "Köklerin yer çekimi yönünde aşağı doğru büyümesine ne denir?", d: "Gravitropizma", y: ["Fototropizma", "Fotosentez"], a: "Gravitropizma (jeotropizma) sayesinde kökler aşağı, gövde yukarı doğru büyür. Tohum ters ekilse bile kök aşağı yönelir." },
  { id: "p07-058", k: "Doğa", s: "Bitkinin ışığa doğru eğilmesini sağlayan hormon hangisidir?", d: "Oksin", y: ["Etilen", "Absisik asit"], a: "Oksin gölgede kalan tarafta birikir ve oradaki hücrelerin uzamasını sağlar. Böylece gövde ışığa doğru eğilir." },
  { id: "p07-059", k: "Doğa", s: "Meyvelerin olgunlaşmasını hızlandıran gaz hâlindeki bitki hormonu hangisidir?", d: "Etilen", y: ["Giberelin", "Sitokinin"], a: "Olgunlaşan meyveler etilen gazı salar. Bu yüzden ham meyve, olgun bir muzla aynı torbaya konursa daha çabuk olgunlaşır." },
  { id: "p07-060", k: "Doğa", s: "Kuraklıkta stomaların kapanmasını sağlayan bitki hormonu hangisidir?", d: "Absisik asit", y: ["Etilen", "Giberelin"], a: "Su sıkıntısında absisik asit miktarı artar ve bekçi hücrelerinin stomaları kapatmasını sağlar. Böylece su kaybı azalır." },
  { id: "p07-061", k: "Doğa", s: "Dokunulunca yapraklarını hızla kapatan bitki hangisidir?", d: "Küstüm otu", y: ["Sardunya", "Fesleğen"], a: "Küstüm otu (Mimosa pudica) dokunulduğunda, yaprak tabanındaki hücrelerin hızla su kaybetmesiyle yapraklarını kapatır." },
  { id: "p07-062", k: "Doğa", s: "Bitki hücre duvarının ana yapı maddesi hangisidir?", d: "Selüloz", y: ["Kitin", "Keratin"], a: "Bitki hücre duvarı büyük ölçüde selülozdan oluşur. Selüloz, glikoz birimlerinden yapılmış uzun zincirli bir moleküldür." },
  { id: "p07-063", k: "Doğa", s: "Şişe tıpası yapımında kullanılan mantar, hangi ağacın kabuğundan elde edilir?", d: "Mantar meşesi", y: ["Kızılçam", "Kayın"], a: "Mantar meşesinin (Quercus suber) kalın kabuğu ağaca zarar vermeden belli aralıklarla soyulur ve yeniden oluşur." },
  { id: "p07-064", k: "Doğa", s: "Ağaçların yıllık halkalarını inceleyerek yaş ve geçmiş iklimi belirleyen bilim dalı hangisidir?", d: "Dendrokronoloji", y: ["Palinoloji", "Paleontoloji"], a: "Dendrokronoloji, halka genişliklerinden ağacın yaşını ve geçmiş yıllardaki kurak ya da yağışlı dönemleri çıkarır." },
  { id: "p07-065", k: "Doğa", s: "Mevsimsel iklimde bir ağacın gövdesindeki tek bir yıllık halka genellikle neyi gösterir?", d: "Bir yıllık büyümeyi", y: ["Bir aylık büyümeyi", "On yıllık büyümeyi"], a: "İlkbaharda açık renkli, yaz sonunda daha koyu odun oluşur. Bu iki tabaka birlikte bir yıllık büyümeyi gösterir." },
  { id: "p07-066", k: "Doğa", s: "Bir ağaç gövdesindeki odunun büyük kısmı hangi hücrelerden oluşur?", d: "Ölü ksilem hücreleri", y: ["Canlı floem hücreleri", "Kloroplastlı hücreler"], a: "Odunu oluşturan ksilem hücrelerinin çoğu olgunlaştığında ölür ve geriye su taşıyan sert duvarlar kalır. Canlı kısım ince bir tabakadır." },
  { id: "p07-067", k: "Doğa", s: "Sonbaharda klorofil yıkılınca yapraklarda ortaya çıkan sarı-turuncu pigmentler hangileridir?", d: "Karotenoitler", y: ["Fikosiyaninler", "Melaninler"], a: "Karotenoitler yaz boyunca da yaprakta bulunur ama klorofilin yeşili onları örter. Klorofil yıkılınca sarı ve turuncu renkler görünür." },
  { id: "p07-068", k: "Doğa", s: "Bazı yaprakların sonbaharda kızarmasını sağlayan, çoğu kez o mevsimde yeni üretilen pigment hangisidir?", d: "Antosiyanin", y: ["Klorofil", "Karoten"], a: "Antosiyaninler kırmızı-mor renk verir. Birçok ağaçta sonbaharda yaprakta kalan şekerlerden yeni olarak üretilir." },
  { id: "p07-069", k: "Doğa", s: "İğne yapraklı olduğu hâlde kışın yapraklarını döken ağaç hangisidir?", d: "Melez", y: ["Karaçam", "Ladin"], a: "Melez (Larix) bir kozalaklı ağaçtır ama yaprak dökendir. Sonbaharda iğneleri sararıp dökülür, ilkbaharda yenileri çıkar." },
  { id: "p07-070", k: "Doğa", s: "Dünyanın en uzun boylu ağaç türü olarak bilinen ağaç hangisidir?", d: "Sahil sekoyası", y: ["Baobab", "Sedir"], a: "Kaliforniya kıyılarında yetişen sahil sekoyaları 100 metreyi aşan boylara ulaşabilir. Bilinen en uzun ağaçlar bu türdendir." },
  { id: "p07-071", k: "Doğa", s: "Afrika'da gövdesinde büyük miktarda su depolayan, \"ters ağaç\" diye de anılan ağaç hangisidir?", d: "Baobab", y: ["Sekoya", "Ladin"], a: "Baobabın kalın gövdesi çok miktarda su depolar. Yapraksız dönemdeki dalları köke benzediği için \"ters ağaç\" denir." },
  { id: "p07-072", k: "Doğa", s: "Bambu hangi bitki ailesine aittir?", d: "Buğdaygiller", y: ["Palmiyeler", "Eğrelti otları"], a: "Bambu, odunsu gövdeli dev bir ottur. Buğday, arpa ve mısırla aynı aileden (buğdaygiller) gelir." },
  { id: "p07-073", k: "Doğa", s: "Dinozorlar çağından bugüne çok az değişerek ulaştığı için \"yaşayan fosil\" denen ağaç hangisidir?", d: "Ginkgo", y: ["Okaliptüs", "Kavak"], a: "Ginkgo biloba, yaklaşık 200 milyon yıl öncesine uzanan bir grubun yaşayan tek türüdür. Yelpaze biçimli yaprakları fosillerdekine çok benzer." },
  { id: "p07-074", k: "Doğa", s: "Doğal kauçuk, kauçuk ağacının neyinden elde edilir?", d: "Sütümsü özsuyundan", y: ["Kabuk liflerinden", "Tohum yağından"], a: "Kauçuk ağacının kabuğu çizilince lateks denen beyaz, sütümsü bir sıvı akar. Bu sıvı işlenerek doğal kauçuk elde edilir." },
  { id: "p07-075", k: "Doğa", s: "Akçaağaç şurubu nasıl elde edilir?", d: "Ağacın özsuyu kaynatılarak", y: ["Yaprakları ezilerek", "Çiçek nektarından"], a: "İlkbahar başında şeker akçaağacından toplanan özsu kaynatılıp suyu uçurularak koyulaştırılır. Bir litre şurup için çok miktarda özsu gerekir." },
  { id: "p07-076", k: "Doğa", s: "Fotosentezde ışık enerjisi hangi enerji türüne dönüştürülür?", d: "Kimyasal enerji", y: ["Ses enerjisi", "Nükleer enerji"], a: "Bitkiler ışık enerjisini şeker moleküllerinin bağlarında kimyasal enerji olarak depolar. Besin zincirinin enerjisi buradan gelir." },
  { id: "p07-077", k: "Doğa", s: "Hangisi sıcak ortamlara uyumlu C4 fotosentezi yapan bir bitkidir?", d: "Mısır", y: ["Buğday", "Pirinç"], a: "Mısır ve şeker kamışı C4 bitkisidir; sıcak ve parlak ortamda karbondioksidi daha verimli kullanır. Buğday ve pirinç C3 bitkisidir." },
  { id: "p07-078", k: "Doğa", s: "Kaktüs gibi CAM bitkileri su kaybını azaltmak için stomalarını ne zaman açar?", d: "Gece", y: ["Öğle saatlerinde", "Yalnız yağmurda"], a: "CAM bitkileri karbondioksidi serin gecelerde alıp depolar, gündüz stomaları kapalıyken fotosentezde kullanır. Böylece az su kaybeder." },
  { id: "p07-079", k: "Doğa", s: "17. yüzyılda söğüt deneyiyle bitki kütlesinin topraktan gelmediğini gösteren bilim insanı kimdir?", d: "Jan van Helmont", y: ["Gregor Mendel", "Charles Darwin"], a: "Van Helmont, beş yıl büyüttüğü söğüt çok kilo alırken saksıdaki toprağın neredeyse hiç azalmadığını gördü. Kütlenin sudan geldiği sonucuna vardı." },
  { id: "p07-080", k: "Doğa", s: "Mumun kapalı kapta tükettiği havanın bir bitkiyle \"yenilendiğini\" 1771'de gösteren kimdir?", d: "Joseph Priestley", y: ["Louis Pasteur", "Robert Hooke"], a: "Priestley, mum sönen kapalı kaba nane koydu. Bir süre sonra mum yeniden yanabildi. Bu deney, bitkilerin oksijen ürettiğinin ilk ipuçlarındandır." },
  { id: "p07-081", k: "Doğa", s: "Bitkilerin havayı yalnızca ışıkta \"temizlediğini\" gösteren 18. yüzyıl bilim insanı kimdir?", d: "Jan Ingenhousz", y: ["Robert Brown", "Gregor Mendel"], a: "Ingenhousz, 1779'da yaptığı deneylerle bitkilerin oksijen üretmek için ışığa, özellikle yeşil kısımlarına ihtiyaç duyduğunu gösterdi." },
  { id: "p07-082", k: "Doğa", s: "Şişe mantarını mikroskopla inceleyip \"hücre\" terimini ilk kullanan bilim insanı kimdir?", d: "Robert Hooke", y: ["Charles Darwin", "Louis Pasteur"], a: "Hooke, 1665'te yayımladığı Micrographia'da mantar dokusundaki küçük boşlukları manastır odalarına benzetip \"hücre\" adını verdi." },
  { id: "p07-083", k: "Doğa", s: "Yaprak yüzeyini kaplayıp su kaybını azaltan mumsu tabakaya ne denir?", d: "Kütikula", y: ["Stoma", "Kambiyum"], a: "Kütikula, epidermis hücrelerinin salgıladığı mumsu bir tabakadır. Kurak bölgelerdeki bitkilerde genellikle daha kalındır." },
  { id: "p07-084", k: "Doğa", s: "Yaprakta fotosentezin en yoğun yapıldığı, sık dizili uzun hücre tabakası hangisidir?", d: "Palizat parankiması", y: ["Epidermis", "Kütikula"], a: "Palizat parankiması yaprağın üst yüzeyinin hemen altındadır. Hücreleri kloroplastça çok zengindir." },
  { id: "p07-085", k: "Doğa", s: "Bitkilerin çoğu azotu topraktan genellikle hangi biçimde alır?", d: "Nitrat iyonu", y: ["Azot gazı", "Azot dioksit gazı"], a: "Havadaki azot gazını bitkiler doğrudan kullanamaz. Azotu topraktan çoğunlukla nitrat ve amonyum iyonları hâlinde alırlar." },
  { id: "p07-086", k: "Doğa", s: "Klorofil molekülünün merkezinde hangi element bulunur?", d: "Magnezyum", y: ["Demir", "Kalsiyum"], a: "Klorofilin merkezinde bir magnezyum atomu vardır. Magnezyum eksikliğinde yapraklar sararır." },
  { id: "p07-087", k: "Doğa", s: "Uzun ağaçlarda suyu yukarı çeken başlıca güç nedir?", d: "Yapraklardaki terleme", y: ["Kökteki kas benzeri pompa", "Floemdeki şeker akışı"], a: "Yapraklardan buharlaşan su, ksilemdeki kesintisiz su sütununu yukarı çeker. Su moleküllerinin birbirine tutunması bu sütunun kopmasını önler." },
  { id: "p07-088", k: "Doğa", s: "Bitkiler hücresel solunumu ne zaman yapar?", d: "Gece ve gündüz sürekli", y: ["Yalnız gece", "Yalnız gündüz"], a: "Bitkiler gündüz fotosentez yapar ama solunum hiç durmaz. Gündüz fotosentez solunumdan fazla olduğu için dışarıya net oksijen verilir." },
  { id: "p07-089", k: "Doğa", s: "Calvin döngüsü için gereken enerjiyi taşıyan, ışık tepkimelerinde üretilen moleküller hangileridir?", d: "ATP ve NADPH", y: ["Glikoz ve su", "DNA ve RNA"], a: "Işık tepkimeleri ATP ve NADPH üretir. Calvin döngüsü bu molekülleri kullanarak karbondioksidi şekere çevirir." },
  { id: "p07-090", k: "Doğa", s: "Kırmızı pancara koyu kırmızı rengini veren pigment grubu hangisidir?", d: "Betalainler", y: ["Klorofiller", "Karotenler"], a: "Pancarın rengi betalain denen pigmentlerden gelir. Bu pigmentler çoğu bitkide değil, karanfil takımındaki az sayıda bitkide bulunur." },
  { id: "p07-091", k: "Doğa", s: "Havuç ve turpta görülen, kalın tek bir ana kökten oluşan kök tipine ne denir?", d: "Kazık kök", y: ["Saçak kök", "Hava kökü"], a: "Kazık kökte kalın bir ana kök derine iner, yan kökler ondan çıkar. Havuç ve turpta bu ana kök besin depolar." },
  { id: "p07-092", k: "Doğa", s: "Buğday gibi tek çeneklilerde görülen, birbirine benzer çok sayıda ince kökten oluşan kök tipi hangisidir?", d: "Saçak kök", y: ["Kazık kök", "Yumru kök"], a: "Saçak kökte belirgin bir ana kök yoktur. Çok sayıda ince kök toprağın üst katmanına yayılır ve toprağı sıkıca tutar." },
  { id: "p07-093", k: "Doğa", s: "Duvar sarmaşığının yüzeylere tutunmasını sağlayan, gövdeden çıkan köklere ne denir?", d: "Hava kökleri", y: ["Kazık kökler", "Yumru kökler"], a: "Duvar sarmaşığı (Hedera) gövdesinden çıkan kısa hava kökleriyle duvar ve ağaç gövdelerine yapışarak tırmanır." },
  { id: "p07-094", k: "Doğa", s: "Yaprak sapı ile gövde arasındaki açıda bulunan ve yeni dal verebilen yapı hangisidir?", d: "Koltuk tomurcuğu", y: ["Kök şapkası", "Stoma"], a: "Koltuk tomurcukları yan dalları ve çiçekleri oluşturur. Uç tomurcuk kesilince genellikle daha çok gelişir; budamada bundan yararlanılır." },
  { id: "p07-095", k: "Doğa", s: "Bitkinin gövde, yaprak ya da kök parçasından yeni birey oluşturmasına ne denir?", d: "Vejetatif üreme", y: ["Çift döllenme", "Tozlaşma"], a: "Vejetatif üremede tohum gerekmez; yeni bitki ana bitkinin genetik kopyasıdır. Çelikle çoğaltma bunun bir örneğidir." },
  { id: "p07-096", k: "Doğa", s: "Çileğin toprak üstünde sürünerek yeni bitkiler oluşturan gövdelerine ne denir?", d: "Stolon", y: ["Rizom", "Yumru"], a: "Stolonlar toprak yüzeyinde yatay uzanır. Boğumlarından kök ve yaprak çıkarak yeni çilek bitkileri oluşur." },
  { id: "p07-097", k: "Doğa", s: "Polen tanesinin tepecikten yumurtalığa doğru uzattığı yapıya ne denir?", d: "Polen tüpü", y: ["Sapçık", "Kök tüyü"], a: "Polen tüpü dişicik borusu içinde ilerleyerek spermleri tohum taslağına ulaştırır. Böylece döllenme gerçekleşir." },
  { id: "p07-098", k: "Doğa", s: "Hem erkek hem dişi organ taşıyan çiçeğe ne denir?", d: "Erdişi çiçek", y: ["Tek eşeyli çiçek", "Kısır çiçek"], a: "Gül, lale ve elma çiçeği gibi çiçeklerin çoğu erdişidir; aynı çiçekte hem ercik hem dişicik bulunur." },
  { id: "p07-099", k: "Doğa", s: "Kivi gibi erkek ve dişi çiçekleri ayrı bireylerde bulunan bitkilere ne denir?", d: "İki evcikli", y: ["Tek evcikli", "Erdişi"], a: "Kivide meyve yalnız dişi bitkilerde oluşur. Bahçelerde tozlaşma için dişi bitkilerin yanına erkek bitkiler de dikilir." },
  { id: "p07-100", k: "Doğa", s: "Mutfakta sebze sayılan domates, botanik açıdan nedir?", d: "Meyve", y: ["Kök", "Gövde"], a: "Botanikte meyve, çiçeğin yumurtalığından gelişen ve tohum taşıyan yapıdır; domates bu tanıma uyar. Mutfakta ise tadı nedeniyle sebze sayılır." },
  { id: "p07-101", k: "Doğa", s: "Çileğin yüzeyindeki küçük sarı \"tohumlar\" botanik olarak nedir?", d: "Asıl meyveler", y: ["Polen keseleri", "Tomurcuklar"], a: "Her biri içinde tek tohum bulunan küçük kuru meyvedir (aken). Kırmızı etli kısım ise şişkinleşen çiçek tablasından gelişir." },
  { id: "p07-102", k: "Doğa", s: "Botanik tanıma göre hangisi üzümsü meyvedir (berry)?", d: "Muz", y: ["Çilek", "Ahududu"], a: "Botanikte muz, domates ve üzüm üzümsü meyvedir. Adlarına rağmen çilek ve ahududu bu gruba girmez." },
  { id: "p07-103", k: "Doğa", s: "Tek bir çiçekteki çok sayıda dişiciğin küçük meyvelerinden oluşan ahududu hangi meyve tipindedir?", d: "Toplu meyve", y: ["Üzümsü meyve", "Kapsül meyve"], a: "Ahududu ve böğürtlende her tanecik ayrı bir dişicikten gelişen küçük sert çekirdekli bir meyvedir. Hepsi birlikte toplu meyveyi oluşturur." },
  { id: "p07-104", k: "Doğa", s: "Çok sayıda çiçeğin meyvelerinin kaynaşmasıyla oluşan birleşik meyveye örnek hangisidir?", d: "Ananas", y: ["Elma", "Kayısı"], a: "Ananas, bir çiçek durumundaki yüzlerce çiçeğin meyvelerinin kaynaşmasıyla oluşur. Kabuğundaki altıgen desenlerin her biri bir çiçekten gelir." },
  { id: "p07-105", k: "Doğa", s: "Kiraz ve şeftali gibi etli kısmın ortasında tek sert çekirdek bulunan meyvelere ne denir?", d: "Sert çekirdekli meyve", y: ["Üzümsü meyve", "Kapsül meyve"], a: "Bu meyvelerde meyve duvarının iç katmanı taş gibi sertleşir ve tohumu sarar. Erik, zeytin ve kayısı da bu gruptandır." },
  { id: "p07-106", k: "Doğa", s: "Elmanın yenen etli kısmının büyük bölümü çiçeğin hangi kısmından gelişir?", d: "Çiçek tablası", y: ["Taç yapraklar", "Ercikler"], a: "Elmada etli kısmın çoğu yumurtalığı saran çiçek tablasından gelişir. Bu yüzden elmaya yalancı meyve denir; asıl meyve ortadaki çekirdek evidir." },
  { id: "p07-107", k: "Doğa", s: "Yer fıstığı hangi bitki ailesine aittir?", d: "Baklagiller", y: ["Gülgiller", "Buğdaygiller"], a: "Yer fıstığı bir baklagildir. Döllenen çiçeğin sapı toprağa doğru uzar ve meyve toprak altında olgunlaşır." },
  { id: "p07-108", k: "Doğa", s: "Yediğimiz badem içi botanik olarak nedir?", d: "Tohum", y: ["Meyve eti", "Kök"], a: "Badem, şeftaliye yakın bir ağacın sert çekirdekli meyvesidir. Yediğimiz kısım, sert kabuğun içindeki tohumdur." },
  { id: "p07-109", k: "Doğa", s: "Hindistan cevizi botanik olarak hangi meyve tipindedir?", d: "Sert çekirdekli meyve", y: ["Üzümsü meyve", "Toplu meyve"], a: "Hindistan cevizi lifli bir dış katmanı ve sert bir iç çekirdeği olan sert çekirdekli meyvedir. Beyaz kısım ve suyu tohumun besin dokusudur." },
  { id: "p07-110", k: "Doğa", s: "Hindistan cevizi tohumları adalar ve kıyılar arasında başlıca nasıl yayılır?", d: "Denizde yüzerek", y: ["Rüzgârla uçarak", "Kuşlarla taşınarak"], a: "Lifli ve hava dolu kabuğu sayesinde Hindistan cevizi denizde uzun süre yüzebilir ve uzak kıyılarda çimlenebilir." },
  { id: "p07-111", k: "Doğa", s: "Karahindiba tohumları başlıca hangi yolla yayılır?", d: "Rüzgârla", y: ["Suyla", "Karıncalarla"], a: "Karahindiba tohumlarının ucunda paraşüte benzeyen ince tüyler vardır. Bu tüyler sayesinde rüzgârla uzaklara taşınır." },
  { id: "p07-112", k: "Doğa", s: "Hayvan tüylerine takılan tohumlarıyla cırt cırt bandın icadına ilham veren bitki hangisidir?", d: "Dulavratotu", y: ["Papatya", "Lale"], a: "İsviçreli mühendis George de Mestral, köpeğinin tüylerine yapışan dulavratotu tohumlarındaki küçük kancaları inceleyerek cırt cırt bandı geliştirdi." },
  { id: "p07-113", k: "Doğa", s: "Akçaağaç tohumlarının kanatlı yapısı ne işe yarar?", d: "Rüzgârla uzağa taşınmaya", y: ["Suda batmaya", "Toprağa gömülmeye"], a: "Kanatlı akçaağaç tohumları düşerken pervane gibi döner. Bu yavaş düşüş rüzgârın onları ana ağaçtan uzaklaştırmasına fırsat verir." },
  { id: "p07-114", k: "Doğa", s: "Kuşların yediği etli meyvelerin tohumları çoğunlukla nasıl yayılır?", d: "Dışkıyla", y: ["Rüzgârla", "Suyla"], a: "Birçok tohum sindirim sisteminden zarar görmeden geçer ve dışkıyla başka bir yere bırakılır. Meyvenin tatlı eti bu taşıma hizmetinin ödülüdür." },
  { id: "p07-115", k: "Doğa", s: "Çoğu tohumun çimlenmeye başlaması için ilk olarak neyi alması gerekir?", d: "Su", y: ["Gübre", "Toprak"], a: "Tohum önce su alıp şişer, bu da enzimleri harekete geçirir. Islak bir pamuk üzerinde toprak olmadan da çimlenebilir." },
  { id: "p07-116", k: "Doğa", s: "Tohumun içindeki, yeni bitkiye dönüşecek küçük bitki taslağına ne denir?", d: "Embriyo", y: ["Endosperm", "Tohum kabuğu"], a: "Embriyo; kökçük, gövdecik ve çenek yapraklarından oluşur. Endosperm ya da çenekler ona çimlenme sırasında besin sağlar." },
  { id: "p07-117", k: "Doğa", s: "Çimlenen bir tohumdan genellikle ilk çıkan yapı hangisidir?", d: "Kökçük", y: ["Yaprak", "Çiçek"], a: "Çimlenmede genellikle önce kökçük çıkar. Böylece fide su almaya ve kendini toprağa tutturmaya erkenden başlar." },
  { id: "p07-118", k: "Doğa", s: "Fasulye çimlenince toprak üstüne çıkan iki kalın, besin depolayan yaprağa ne denir?", d: "Çenek yaprakları", y: ["Çanak yapraklar", "Sülükler"], a: "Çenek yaprakları tohumdaki embriyonun ilk yapraklarıdır. Fasulyede besin depolar ve gerçek yapraklar gelişene kadar fideyi besler." },
  { id: "p07-119", k: "Doğa", s: "Tohumların uygun koşullar gelene kadar çimlenmeden beklemesine ne denir?", d: "Dormansi", y: ["Tozlaşma", "Terleme"], a: "Dormansi (uyku hâli), tohumun kış gibi uygun olmayan dönemlerde çimlenmesini engeller. Bazı tohumlar yıllarca canlı kalabilir." },
  { id: "p07-120", k: "Doğa", s: "Masada kalıntılarında bulunan yaklaşık 2.000 yıllık bir tohumdan çimlendirilen bitki hangisidir?", d: "Hurma", y: ["Zeytin", "Buğday"], a: "İsrail'deki Masada kazısında bulunan yaklaşık 2.000 yıllık hurma çekirdeği 2005'te çimlendirildi. Fidan \"Methuselah\" adıyla bilinir." },
  { id: "p07-121", k: "Doğa", s: "Bitkiler âleminin en büyük tohumunu üreten palmiye hangisidir?", d: "Coco de mer", y: ["Hindistan cevizi", "Hurma"], a: "Seyşeller'e özgü Coco de mer (Lodoicea maldivica) palmiyesinin tohumu 20 kilogramı aşabilir. Bilinen en büyük tohumdur." },
  { id: "p07-122", k: "Doğa", s: "Kahve çekirdeği bitkinin hangi kısmıdır?", d: "Meyvenin içindeki tohum", y: ["Kök yumrusu", "Yaprak tomurcuğu"], a: "Kahve bitkisinin kırmızı, kirazı andıran meyvelerinin içinde genellikle iki tohum bulunur. Kavrulan bu tohumlara kahve çekirdeği denir." },
  { id: "p07-123", k: "Doğa", s: "Çikolatanın hammaddesi kakao, kakao ağacının hangi kısmından elde edilir?", d: "Tohumlarından", y: ["Yapraklarından", "Kabuğundan"], a: "Kakao ağacının gövdesinde gelişen iri meyvelerin içinde çok sayıda tohum bulunur. Bu tohumlar fermente edilip kurutulur ve kavrulur." },
  { id: "p07-124", k: "Doğa", s: "Siyah çay ile yeşil çay arasındaki temel fark nedir?", d: "Yaprağın işlenme biçimi", y: ["Bitki türü", "Yetiştiği kıta"], a: "İkisi de Camellia sinensis bitkisinin yapraklarından yapılır. Siyah çayda yapraklar oksitlenmeye bırakılır, yeşil çayda bu süreç ısıyla durdurulur." },
  { id: "p07-125", k: "Doğa", s: "Pamuk lifi, pamuk bitkisinin hangi kısmından gelir?", d: "Tohumu saran tüylerden", y: ["Gövde kabuğundan", "Yapraklarından"], a: "Pamuk lifleri tohumun yüzeyindeki hücrelerin uzamasıyla oluşan tüylerdir. Bu lifler neredeyse tamamen selülozdan oluşur." },
  { id: "p07-126", k: "Doğa", s: "Keten kumaşı, keten bitkisinin hangi kısmından elde edilir?", d: "Gövde liflerinden", y: ["Tohum tüylerinden", "Kök liflerinden"], a: "Keten lifleri bitkinin gövdesinde bulunan uzun ve sağlam liflerdir. Tohumundan ise keten tohumu yağı elde edilir." },
  { id: "p07-127", k: "Doğa", s: "Zeytinyağı zeytin ağacının hangi kısmından elde edilir?", d: "Meyvesinden", y: ["Yapraklarından", "Kabuğundan"], a: "Zeytinyağı, zeytin meyvesinin ezilip sıkılmasıyla elde edilir. Yağın çoğu meyvenin etli kısmında bulunur." },
  { id: "p07-128", k: "Doğa", s: "Mısır ilk kez hangi bölgede evcilleştirilmiştir?", d: "Meksika", y: ["Mısır (ülke)", "Çin"], a: "Mısır, yaklaşık 9.000 yıl önce bugünkü Meksika'da teosinte adlı yabani bir otun seçilerek ıslah edilmesiyle ortaya çıktı." },
  { id: "p07-129", k: "Doğa", s: "Patatesin anavatanı neresidir?", d: "Güney Amerika'daki And Dağları", y: ["İrlanda", "Hindistan"], a: "Patates binlerce yıl önce bugünkü Peru ve Bolivya çevresinde evcilleştirildi. Avrupa'ya 16. yüzyılda İspanyollar getirdi." },
  { id: "p07-130", k: "Doğa", s: "Buğdayın ilk evcilleştirildiği bölge hangisidir?", d: "Bereketli Hilal", y: ["Amazon Havzası", "İskandinavya"], a: "Buğday yaklaşık 10.000 yıl önce, Güneydoğu Anadolu'yu da içine alan Bereketli Hilal'de evcilleştirildi. Genetik çalışmalar Karacadağ çevresini işaret eder." },
  { id: "p07-131", k: "Doğa", s: "En çok içilen kahve türü olan Arabica kahvesinin anavatanı neresidir?", d: "Etiyopya", y: ["Brezilya", "Kolombiya"], a: "Arabica kahvesi Etiyopya'nın dağlık ormanlarından köken alır. Brezilya ve Kolombiya bugün büyük üreticidir ama kahve oraya sonradan götürüldü." },
  { id: "p07-132", k: "Doğa", s: "Acı biberin yakıcılığını veren madde hangisidir?", d: "Kapsaisin", y: ["Kafein", "Mentol"], a: "Kapsaisin, ağızdaki sıcaklık algılayan sinir uçlarını uyarır ve yanma hissi verir. Daha çok meyvenin çekirdeklerini taşıyan beyaz zarlarda bulunur." },
  { id: "p07-133", k: "Doğa", s: "Işıkta yeşillenen patates kabuğunda artabilen zehirli madde hangisidir?", d: "Solanin", y: ["Kafein", "Kapsaisin"], a: "Patates ışık görünce klorofil üretir ve yeşillenir; aynı sırada solanin de artabilir. Yeşillenen kısımların soyulup atılması önerilir." },
  { id: "p07-134", k: "Doğa", s: "Domates, patates, patlıcan ve biber hangi bitki ailesindendir?", d: "Patlıcangiller", y: ["Kabakgiller", "Turpgiller"], a: "Bu bitkilerin hepsi patlıcangiller (Solanaceae) ailesindendir. Tütün de aynı ailenin üyesidir." },
  { id: "p07-135", k: "Doğa", s: "Kabak, karpuz, kavun ve salatalık hangi bitki ailesindendir?", d: "Kabakgiller", y: ["Patlıcangiller", "Baklagiller"], a: "Kabakgiller ailesinin üyeleri genellikle sülüklerle tırmanan ya da yerde sürünen bitkilerdir ve iri, çok tohumlu meyveler verir." },
  { id: "p07-136", k: "Doğa", s: "Lahana, brokoli ve karnabahar hangi yabani bitkinin farklı kültür çeşitleridir?", d: "Yabani lahana", y: ["Yabani turp", "Yabani marul"], a: "Bunların hepsi Brassica oleracea türüdür. Çiftçiler binlerce yıl boyunca yaprağı, tomurcuğu ya da çiçek durumu iri olanları seçerek bu çeşitleri geliştirdi." },
  { id: "p07-137", k: "Doğa", s: "Mercimek, nohut ve fasulye hangi bitki ailesindendir?", d: "Baklagiller", y: ["Buğdaygiller", "Gülgiller"], a: "Baklagillerin tohumları kabuk şeklindeki meyvelerde (bakla) gelişir. Proteince zengin olmaları kökleriyle ortak yaşayan azot bağlayıcı bakterilerle ilgilidir." },
  { id: "p07-138", k: "Doğa", s: "Elma, armut ve çilek hangi bitki ailesindendir?", d: "Gülgiller", y: ["Patlıcangiller", "Kabakgiller"], a: "Gülgiller ailesi elma, armut, kiraz, şeftali, çilek ve badem gibi pek çok meyve bitkisini içerir." },
  { id: "p07-139", k: "Doğa", s: "Çam fıstığı hangi ağaçtan elde edilir?", d: "Fıstık çamı", y: ["Kızılçam", "Sedir"], a: "Çam fıstığı, fıstık çamının (Pinus pinea) iri kozalaklarının pulları arasında gelişen tohumlardır." },
  { id: "p07-140", k: "Doğa", s: "Dünya fındık üretiminde açık ara ilk sırada yer alan ülke hangisidir?", d: "Türkiye", y: ["İtalya", "ABD"], a: "Dünya fındığının yarısından fazlası Türkiye'de, çoğu Karadeniz kıyısında üretilir." },
  { id: "p07-141", k: "Doğa", s: "Şeker kamışı dışında sofra şekerinin elde edildiği başlıca bitki hangisidir?", d: "Şeker pancarı", y: ["Patates", "Havuç"], a: "Sofra şekeri (sakaroz) ya şeker kamışının gövdesinden ya da şeker pancarının kökünden elde edilir. İkisinden çıkan şeker kimyasal olarak aynıdır." },
  { id: "p07-142", k: "Doğa", s: "Sıtma tedavisinde kullanılan kinin hangi ağacın kabuğundan elde edilmiştir?", d: "Kınakına", y: ["Söğüt", "Porsuk"], a: "Kinin, Güney Amerika'ya özgü kınakına (Cinchona) ağacının kabuğundan elde edilir. Yüzyıllarca sıtmaya karşı kullanılan başlıca ilaç oldu." },
  { id: "p07-143", k: "Doğa", s: "Aspirinin öncüsü olan salisilik bileşikler ilk olarak hangi ağacın kabuğunda tanındı?", d: "Söğüt", y: ["Meşe", "Çam"], a: "Söğüt kabuğu ağrı ve ateş için binlerce yıldır kullanılıyordu. İçindeki salisin bileşiği, aspirinin geliştirilmesine yol açtı." },
  { id: "p07-144", k: "Doğa", s: "Yaprakları bir kapan gibi kapanarak böcek yakalayan etçil bitki hangisidir?", d: "Venüs sinekkapanı", y: ["İbrik bitkisi", "Güneşgülü"], a: "Venüs sinekkapanının iki parçalı yaprağı, içine giren böceğin üzerine saniyeden kısa sürede kapanır. Ardından sindirim salgıları avı eritir." },
  { id: "p07-145", k: "Doğa", s: "Venüs sinekkapanının kapanması için tetik tüylerine genellikle nasıl dokunulmalıdır?", d: "Kısa sürede iki kez", y: ["Tek bir kez", "Bir saat boyunca"], a: "Kapan, tetik tüylerine yaklaşık yarım dakika içinde iki dokunuş olunca kapanır. Bu, yağmur damlası gibi tek seferlik uyarılarda boşa kapanmayı önler." },
  { id: "p07-146", k: "Doğa", s: "Venüs sinekkapanı doğal olarak nerede yetişir?", d: "ABD'nin güneydoğusunda", y: ["Amazon ormanlarında", "Borneo adasında"], a: "Venüs sinekkapanı yalnız ABD'deki Kuzey ve Güney Carolina'nın kıyı bataklıklarında doğal olarak yetişir." },
  { id: "p07-147", k: "Doğa", s: "Etçil bitkilerin böcek yakalamasının başlıca nedeni nedir?", d: "Topraktaki azot eksikliği", y: ["Fotosentez yapamamaları", "Su ihtiyacı"], a: "Etçil bitkiler fotosentez yapar. Yaşadıkları bataklık toprakları azotça fakir olduğu için bu besini avlarından sağlarlar." },
  { id: "p07-148", k: "Doğa", s: "İçine düşen böcekleri sıvı dolu ibrik biçimli yapraklarında sindiren bitki hangisidir?", d: "İbrik bitkisi", y: ["Venüs sinekkapanı", "Küstüm otu"], a: "İbrik bitkisinin (Nepenthes) kaygan ağızlı yaprak kaplarına düşen böcekler dışarı çıkamaz ve içteki sıvıda sindirilir." },
  { id: "p07-149", k: "Doğa", s: "Yapraklarındaki yapışkan damlacıklı tüylerle böcek yakalayan etçil bitki hangisidir?", d: "Güneşgülü", y: ["İbrik bitkisi", "Nilüfer"], a: "Güneşgülü (Drosera) tüylerinin ucundaki parlak damlalar çiy gibi görünür ama yapışkandır. Yakalanan böceği tüyler sarar ve sindirir." },
  { id: "p07-150", k: "Doğa", s: "Suda yaşayıp minik keseleriyle avını hızla içine çeken etçil bitki cinsi hangisidir?", d: "Utricularia", y: ["Nymphaea", "Lemna"], a: "Utricularia'nın keseleri içindeki basınç dışarıdan düşüktür. Tetik tüyüne dokunan küçük canlı, kapak açılınca suyla birlikte içeri çekilir." },
  { id: "p07-151", k: "Doğa", s: "Klorofilsiz, sarı iplik gibi gövdesiyle başka bitkilere sarılıp besinini emen parazit bitki hangisidir?", d: "Küsküt", y: ["Duvar sarmaşığı", "Ökse otu"], a: "Küsküt (Cuscuta) neredeyse hiç fotosentez yapmaz. Konakçı bitkinin gövdesine sokulan emeçlerle su ve besin çeker." },
  { id: "p07-152", k: "Doğa", s: "Ağaç dallarında yaşayan, fotosentez yapsa da su ve mineralleri konakçısından alan yarı parazit hangisidir?", d: "Ökse otu", y: ["Küsküt", "Eğrelti otu"], a: "Ökse otu yeşildir ve kendi şekerini üretir. Ancak suyunu ve minerallerini ağacın iletim dokusuna soktuğu yapılarla sağlar." },
  { id: "p07-153", k: "Doğa", s: "Başka bir bitkinin üzerinde yaşayıp ondan besin almayan bitkilere ne denir?", d: "Epifit", y: ["Parazit", "Ayrıştırıcı"], a: "Epifitler, örneğin birçok tropik orkide, ağaçları yalnızca destek olarak kullanır. Suyu yağmurdan ve havadaki nemden alırlar." },
  { id: "p07-154", k: "Doğa", s: "Dünyanın en küçük çiçekli bitkisi olarak bilinen su bitkisi cinsi hangisidir?", d: "Wolffia", y: ["Nilüfer", "Lotus"], a: "Wolffia türleri su yüzeyinde yüzen, birkaç milimetreden küçük bitkilerdir. Kökleri yoktur ve en küçük çiçekli bitkiler olarak bilinir." },
  { id: "p07-155", k: "Doğa", s: "Mikroskobik yüzey yapıları sayesinde suyu iten ve kendini temizleyen yapraklarıyla bilinen bitki hangisidir?", d: "Lotus", y: ["Ispanak", "Marul"], a: "Lotus yaprağına düşen su damlaları yuvarlanıp kirleri de alıp götürür. \"Lotus etkisi\" adı verilen bu özellik kendini temizleyen yüzeylere ilham verdi." },
  { id: "p07-156", k: "Doğa", s: "Amazon'da çapı 2 metreyi aşabilen yüzen yapraklarıyla bilinen bitki hangisidir?", d: "Dev nilüfer", y: ["Su sümbülü", "Su mercimeği"], a: "Victoria cinsi dev nilüferlerin kenarı kalkık yuvarlak yaprakları alttaki kaburgalar sayesinde çok sağlamdır. Küçük bir çocuğu taşıyabilir." },
  { id: "p07-157", k: "Doğa", s: "Ilıman bölgelerdeki birçok ağaç kışın neden yapraklarını döker?", d: "Su kaybını ve don zararını azaltmak", y: ["Yeni çiçeklere yer açmak", "Hayvanlardan korunmak"], a: "Kışın donmuş topraktan su almak zordur. Geniş yaprakları dökmek su kaybını ve dondan zarar görmeyi önler." },
  { id: "p07-158", k: "Doğa", s: "Meşe ağacının meyvesine ne ad verilir?", d: "Palamut", y: ["Kozalak", "Kestane"], a: "Palamut, sert kabuklu bir meyvedir ve tabanında pullu bir kadeh bulunur. İçinde meşenin tohumu vardır." },
  { id: "p07-159", k: "Doğa", s: "Bir ağacın kuru kütlesinin büyük kısmı nereden gelir?", d: "Havadaki karbondioksitten", y: ["Topraktaki minerallerden", "Yağmur suyundaki tuzlardan"], a: "Odunun büyük kısmı karbon ve oksijenden oluşur. Ağaç bunları fotosentezle havadan aldığı karbondioksitten sağlar; topraktan gelen mineraller küçük bir paydır." },
  { id: "p07-160", k: "Doğa", s: "Kehribar neyin fosilleşmesiyle oluşur?", d: "Ağaç reçinesinin", y: ["Bal mumunun", "Ağaç özsuyunun"], a: "Kehribar, milyonlarca yıl önce ağaçlardan akan reçinenin sertleşmesiyle oluşur. İçinde bazen o döneme ait böcekler ve bitki parçaları korunur." },
  { id: "p07-161", k: "Doğa", s: "Isırgan otuna dokununca deride yanma hissi oluşmasının nedeni nedir?", d: "İğne gibi kırılan tüyler", y: ["Yapraktaki sert dikenler", "Kökten salınan gaz"], a: "Isırgan otunun ince tüylerinin ucu dokununca kırılır ve deriye histamin gibi tahriş edici maddeler bırakır." },
  { id: "p07-162", k: "Doğa", s: "Olgunlaşmış ayçiçeği başları genellikle hangi yöne dönük kalır?", d: "Doğu", y: ["Batı", "Kuzey"], a: "Genç ayçiçekleri gün içinde güneşi takip eder. Olgunlaşınca başları doğuya sabitlenir; sabah güneşiyle ısınan çiçekler daha çok arı çeker." },
  { id: "p07-163", k: "Doğa", s: "Tuzlu kıyı bataklıklarında yetişen ve topraktan havaya doğru solunum kökleri çıkaran ağaçlar hangileridir?", d: "Mangrovlar", y: ["Sekoyalar", "Huşlar"], a: "Mangrovların yaşadığı çamur oksijence fakirdir. Yukarı doğru büyüyen solunum kökleri havadan oksijen almalarını sağlar." },
  { id: "p07-164", k: "Doğa", s: "Kaktüslerin neredeyse tamamı doğal olarak hangi kıtalarda yetişir?", d: "Amerika kıtalarında", y: ["Afrika'da", "Avustralya'da"], a: "Kaktüsler Amerika'ya özgüdür; yalnızca bir tür doğal olarak Afrika'da da bulunur. Afrika çöllerindeki benzer bitkiler çoğunlukla sütleğenlerdir." },
  { id: "p07-165", k: "Doğa", s: "Aloe vera gibi yaprak ya da gövdelerinde su depolayan bitkilere ne denir?", d: "Sukulent", y: ["Epifit", "Parazit"], a: "Sukulent bitkiler etli dokularında su depolar. Kurak bölgelerde uzun süre yağmur olmadan yaşayabilirler." },
  { id: "p07-166", k: "Doğa", s: "İncir ağacının çiçekleri nerede bulunur?", d: "Meyve gibi görünen yapının içinde", y: ["Dalların ucunda açıkta", "Toprak altında"], a: "İncirin içi dışa kapalı bir çiçek durumudur ve yüzlerce küçük çiçek bu yapının iç yüzünü kaplar. Bu yüzden incir çiçeği dışarıdan görünmez." },
  { id: "p07-167", k: "Doğa", s: "Naneye serinletici etkisini veren madde hangisidir?", d: "Mentol", y: ["Kapsaisin", "Kafein"], a: "Mentol, soğuğu algılayan sinir uçlarını uyarır. Bu yüzden ortam sıcaklığı değişmese de ağızda serinlik hissi verir." },
  { id: "p07-168", k: "Doğa", s: "Kahve ve çay bitkilerinde kafeinin bitki için bilinen işlevlerinden biri nedir?", d: "Böceklere karşı savunma", y: ["Fotosentezi hızlandırma", "Çiçeğe renk verme"], a: "Kafein birçok böcek için acı ve zehirlidir; yaprak ve tohumları yenmekten korur. Düşük miktarda nektarda bulunması ise arıların çiçeği hatırlamasına yardım eder." },
  { id: "p07-169", k: "Doğa", s: "Oduna sertliğini veren ve hücre duvarlarını güçlendiren madde hangisidir?", d: "Lignin", y: ["Kitin", "Keratin"], a: "Lignin, odunsu hücre duvarlarında selüloz liflerinin arasını dolduran sert bir polimerdir. Ağaçların dik durabilmesini sağlar." },
  { id: "p07-170", k: "Doğa", s: "Marketlerde satılan muzlar genellikle nasıl çoğaltılır?", d: "Yan sürgünlerle", y: ["Tohumla", "Çapraz tozlaşmayla"], a: "Ticari muzlarda işe yarar tohum yoktur. Ana bitkinin dibinden çıkan sürgünlerle ya da doku kültürüyle çoğaltılır, bu yüzden genetik olarak birbirine çok benzerler." },
  { id: "p07-171", k: "Doğa", s: "Bir elma çeşidini aynı özellikleriyle çoğaltmak için meyve bahçelerinde yaygın kullanılan yöntem hangisidir?", d: "Aşılama", y: ["Tohumdan yetiştirme", "Tozlaşma"], a: "Elma tohumundan çıkan ağaç ana çeşide benzemez. Bu yüzden istenen çeşitten alınan dal parçası bir anaç ağaca aşılanır." },
  { id: "p07-172", k: "Doğa", s: "Çekirdeksiz karpuzlar nasıl elde edilir?", d: "Triploit melezler üretilerek", y: ["Tohumlar ışınlanarak", "Meyveye hormon enjekte edilerek"], a: "Kromozom takımı sayısı farklı iki bitki çaprazlanınca üç takım kromozomlu (triploit) bitkiler oluşur. Bunlar olgun tohum yapamaz." },
  { id: "p07-173", k: "Doğa", s: "Bir yaprakta nişasta olup olmadığını mavi-siyah renk vererek gösteren madde hangisidir?", d: "İyot çözeltisi", y: ["Tuzlu su", "Sirke"], a: "İyot nişastayla tepkimeye girerek koyu mavi-siyah renk verir. Okul deneylerinde ışık alan yapraklarda nişasta üretildiği böyle gösterilir." },
  { id: "p07-174", k: "Doğa", s: "İlkbaharda çam ormanı yakınındaki arabaları ve göl yüzeylerini kaplayan sarı tozun yaygın kaynağı nedir?", d: "Çam poleni", y: ["Çöl tozu", "Mantar sporu"], a: "Çamlar rüzgârla tozlaşır ve çok miktarda polen saçar. Polenlerindeki küçük hava keseleri uzaklara taşınmalarını kolaylaştırır." },
  { id: "p07-175", k: "Doğa", s: "Enginarın yenen kısmı botanik olarak nedir?", d: "Olgunlaşmamış çiçek başı", y: ["Kök", "Meyve"], a: "Enginar, devedikeni akrabası bir bitkinin açmamış çiçek başıdır. Hasat edilmezse mor renkli büyük bir çiçeğe dönüşür." },
  { id: "p07-176", k: "Doğa", s: "Kuşkonmazın yenen kısmı nedir?", d: "Genç gövde sürgünleri", y: ["Kök", "Çiçek sapı"], a: "Kuşkonmaz, topraktaki gövdeden ilkbaharda çıkan genç sürgünler yumuşakken kesilerek hasat edilir." },
  { id: "p07-177", k: "Doğa", s: "Mısır tanesi ısıtılınca patlamasının nedeni nedir?", d: "İçindeki suyun buharlaşması", y: ["İçindeki havanın genleşmesi", "Kabuğun erimesi"], a: "Tanenin içindeki az miktar su ısınınca buhara dönüşür. Sert kabuk basınca dayanamayıp patlar ve nişasta kabarır." },
  { id: "p07-178", k: "Doğa", s: "Ağaç kabuğunda gaz alışverişini sağlayan küçük açıklıklara ne denir?", d: "Lentisel", y: ["Stoma", "Tepecik"], a: "Lentiseller gövde ve dal kabuğundaki gözeneklerdir. Kiraz ve huş ağacı kabuğunda yatay çizgiler hâlinde kolayca görülebilir." },
  { id: "p07-179", k: "Doğa", s: "Bitki gövdesinde yaprakların çıktığı noktalara ne denir?", d: "Boğum", y: ["Lentisel", "Kök şapkası"], a: "Boğumlar yaprak ve tomurcukların bağlandığı yerlerdir. İki boğum arasındaki gövde parçasına boğum arası denir." },
  { id: "p07-180", k: "Doğa", s: "Bitki kökleri topraktan suyu başlıca hangi süreçle alır?", d: "Osmoz", y: ["Fotosentez", "Terleme"], a: "Kök hücrelerinin içi topraktaki sudan daha yoğun çözelti içerir. Su, yarı geçirgen zardan bu yoğun tarafa doğru, osmozla geçer." },
  { id: "p07-181", k: "Doğa", s: "Bir saksı bitkisi sürekli çok tuzlu suyla sulanırsa genellikle ne olur?", d: "Su kaybedip solar", y: ["Daha hızlı büyür", "Daha çok çiçek açar"], a: "Toprak suyu çok tuzlu olunca su köke girmek yerine kökten dışarı çıkmaya yönelir. Bitki su alamaz ve solar." },
  { id: "p07-182", k: "Doğa", s: "Gübrelerde bulunan, bitkiler için en önemli üç besin elementi hangileridir?", d: "Azot, fosfor, potasyum", y: ["Sodyum, klor, demir", "Helyum, neon, argon"], a: "Gübre ambalajlarındaki NPK harfleri azot, fosfor ve potasyumu gösterir. Bitkiler bunları topraktan en çok miktarda alır." },
  { id: "p07-183", k: "Doğa", s: "Bir yıl içinde çimlenip çiçek açan, tohum verip ölen bitkilere ne denir?", d: "Tek yıllık", y: ["Çok yıllık", "Herdem yeşil"], a: "Tek yıllık bitkiler yaşam döngüsünü bir mevsimde tamamlar ve tohumlarıyla bir sonraki yıla geçer. Ayçiçeği ve fasulye buna örnektir." },
  { id: "p07-184", k: "Doğa", s: "Havuç gibi ilk yıl kökünde besin depolayıp ikinci yıl çiçek açan bitkilere ne denir?", d: "İki yıllık", y: ["Tek yıllık", "Çok yıllık"], a: "İki yıllık bitkiler ilk yıl yaprak ve depo organı geliştirir, ikinci yıl çiçek ve tohum verip ölür. Havucu ilk yıl hasat ettiğimiz için çiçeğini pek görmeyiz." },
  { id: "p07-185", k: "Doğa", s: "Gövde uzamasını ve tohum çimlenmesini teşvik eden, ilk kez bir mantarda keşfedilen hormon hangisidir?", d: "Giberelin", y: ["Oksin", "Absisik asit"], a: "Giberelin, çeltik fidelerini anormal uzatan Gibberella mantarı incelenirken keşfedildi. Daha sonra bitkilerin de bu hormonu ürettiği anlaşıldı." },
  { id: "p07-186", k: "Doğa", s: "Bitkilerin çiçeklenme zamanını gece ve gündüz uzunluğuna göre ayarlamasına ne denir?", d: "Fotoperiyodizm", y: ["Fototropizma", "Fotoliz"], a: "Bazı bitkiler günler uzayınca, bazıları kısalınca çiçek açar. Örneğin kasımpatı kısa gün bitkisidir ve sonbaharda açar." },
  { id: "p07-187", k: "Doğa", s: "Polen ve sporları inceleyen bilim dalı hangisidir?", d: "Palinoloji", y: ["Mikoloji", "Entomoloji"], a: "Polenlerin dış duvarı çok dayanıklıdır ve tortularda binlerce yıl korunur. Palinologlar bunlardan geçmişteki bitki örtüsünü ve iklimi çıkarır." },
  { id: "p07-188", k: "Doğa", s: "Bitkileri inceleyen bilim dalına ne ad verilir?", d: "Botanik", y: ["Zooloji", "Jeoloji"], a: "Botanik, bitkilerin yapısını, işleyişini, sınıflandırmasını ve ekolojisini inceler. Zooloji hayvanları, jeoloji ise yer bilimini konu alır." },
  { id: "p07-189", k: "Doğa", s: "Canlılara iki kelimeli Latince ad verme sistemini yaygınlaştıran bilim insanı kimdir?", d: "Carl Linnaeus", y: ["Charles Darwin", "Gregor Mendel"], a: "İsveçli Linnaeus, 18. yüzyılda her türe cins ve tür adından oluşan iki kelimelik bir ad verilmesini sistemleştirdi. Örneğin buğday Triticum aestivum'dur." },
  { id: "p07-190", k: "Doğa", s: "Quercus robur gibi bilimsel bir türadındaki iki kelime neyi gösterir?", d: "Cins ve tür", y: ["Aile ve takım", "Bölge ve renk"], a: "İlk kelime cinsi (Quercus: meşe), ikinci kelime türü belirtir. Cins adı büyük harfle başlar ve ad genellikle italik yazılır." },
  { id: "p07-191", k: "Doğa", s: "Yaprak damarlarının içinde neler bulunur?", d: "Ksilem ve floem", y: ["Hava boşlukları", "Kök tüyleri"], a: "Yaprak damarları iletim demetleridir. Ksilem yaprağa su getirir, floem ise üretilen şekeri yapraktan dışarı taşır." },
  { id: "p07-192", k: "Doğa", s: "Bir bitkinin döllenme olmadan tohumsuz meyve oluşturmasına ne denir?", d: "Partenokarpi", y: ["Fotoperiyodizm", "Vernalizasyon"], a: "Partenokarpide meyve döllenme olmadan gelişir, bu yüzden tohum oluşmaz. Ticari muzlar ve bazı salatalık çeşitleri buna örnektir." },
  { id: "p07-193", k: "Doğa", s: "Bazı bitkilerin çiçek açabilmek için bir süre soğuğa maruz kalması gerekliliğine ne denir?", d: "Vernalizasyon", y: ["Partenokarpi", "Fototropizma"], a: "Kışlık buğday gibi bitkiler sonbaharda ekilir. Kışın soğuğunu geçirmeden çiçeklenmezler; böylece çiçekler kışa değil ilkbahara denk gelir." },
  { id: "p07-194", k: "Doğa", s: "Dünyanın dört bir yanından tohum örneklerinin yedeklendiği küresel tohum deposu nerededir?", d: "Svalbard (Norveç)", y: ["Antarktika", "İsviçre Alpleri"], a: "Svalbard Küresel Tohum Deposu, Kuzey Kutbu'na yakın bir adada dağın içine oyulmuştur. Doğal soğuk, tohumların uzun süre korunmasına yardım eder." },
  { id: "p07-195", k: "Doğa", s: "Antik Mısır'da yazı malzemesi olan papirüs, bitkinin hangi kısmından yapılırdı?", d: "Gövdesinin iç dokusundan", y: ["Yapraklarından", "Köklerinden"], a: "Papirüs sazının üçgen kesitli gövdesinin içi ince şeritler hâlinde kesilir, çapraz dizilip preslenirdi. Kuruyunca yazılabilir yapraklar oluşurdu." },
  { id: "p07-196", k: "Doğa", s: "Muz bitkisinin gövde gibi görünen kısmı aslında nedir?", d: "Üst üste sarılmış yaprak kınları", y: ["Odunsu bir gövde", "Kalınlaşmış hava kökleri"], a: "Muz bitkisi ağaç değil, dev bir ottur. Gövde sanılan kısım iç içe sarılmış yaprak kınlarından oluşan yalancı gövdedir." },
  { id: "p07-197", k: "Doğa", s: "Kesilen elmanın bir süre sonra kararmasının nedeni nedir?", d: "Enzimlerin oksijenle tepkimesi", y: ["Bakterilerin üremesi", "Işığın etkisi"], a: "Kesilince hücreler parçalanır ve polifenol oksidaz enzimi havadaki oksijenle tepkimeye girer. Oluşan kahverengi pigmentler kararmaya yol açar." },
  { id: "p07-198", k: "Doğa", s: "Muz olgunlaşırken tatlanmasının nedeni nedir?", d: "Nişastanın şekere dönüşmesi", y: ["Güneşten şeker alması", "Suyunun artması"], a: "Ham muzda karbonhidratın çoğu nişastadır. Olgunlaşma sırasında enzimler nişastayı şekerlere parçalar ve muz tatlanıp yumuşar." },
  { id: "p07-199", k: "Doğa", s: "Bira yapımında kullanılan maltı elde etmek için en çok hangi tahıl çimlendirilir?", d: "Arpa", y: ["Pirinç", "Mısır"], a: "Malt, arpa tanelerinin çimlendirilip kurutulmasıyla elde edilir. Çimlenme sırasında oluşan enzimler nişastayı şekere çevirir." },
  { id: "p07-200", k: "Doğa", s: "Hangi meyve dalından koparıldıktan sonra da olgunlaşmaya devam eder?", d: "Muz", y: ["Çilek", "Üzüm"], a: "Muz, elma ve domates gibi meyveler hasattan sonra etilen üreterek olgunlaşmayı sürdürür. Çilek ve üzüm ise dalda olgunlaştıkları kadar kalır." },
];
